const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const beijing = ee.Geometry.Polygon([
    [115.5, 39.4],
    [117.5, 39.4], 
    [117.5, 41.1],
    [115.5, 41.1],
    [115.5, 39.4]
  ]);

  const janDates = ['2020-01-01', '2020-01-20'];
  const febDates = ['2020-02-10', '2020-02-25'];

  // 2. Data Acquisition
  const janCollection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(janDates[0], janDates[1])
    .filterBounds(beijing)
    .select('tropospheric_NO2_column_number_density');

  const febCollection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(febDates[0], febDates[1])
    .filterBounds(beijing)
    .select('tropospheric_NO2_column_number_density');

  // Check collection sizes
  const janSize = janCollection.size().getInfo();
  const febSize = febCollection.size().getInfo();

  console.log(`Jan Images: ${janSize}, Feb Images: ${febSize}`);

  if (janSize === 0 || febSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean NO2 for each period
  const janMean = janCollection.mean();
  const febMean = febCollection.mean();

  // Count valid pixels
  const janCount = janMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: beijing,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density').getInfo();

  const febCount = febMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: beijing,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density').getInfo();

  console.log(`Jan Pixels: ${janCount}, Feb Pixels: ${febCount}`);

  if (janCount === 0 || febCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Calculate mean values
  const janValue = janMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: beijing,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density').getInfo();

  const febValue = febMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: beijing,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density').getInfo();

  console.log(`Jan NO2: ${janValue?.toFixed(6)}, Feb NO2: ${febValue?.toFixed(6)}`);

  // 4. Validation & Final Answer
  if (janValue === null || febValue === null || 
      isNaN(janValue) || isNaN(febValue) ||
      janValue < 0 || febValue < 0) {
    console.log("<answer>C3</answer>");
  } else if (febValue < janValue) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
